package net.officefloor.hq.app.settings;

/** The settings form: each setting given is saved; one left out (null) stays as it is. The grade terms are by grade.
 *  {@code from} is the from-date given for a dated setting, by key (clerk-limit, floor, terms, terms-<grade>, late-pct,
 *  cap, proof-threshold, note-threshold); blank or left out is the sheet's today. {@code permissions} is the permission matrix entries
 *  given, by action: a comma separated list of roles, blank keeping the standing rule. {@code graceDays} is the grace days, blank meaning off.
 *  {@code entryDate} is the entry date, blank meaning off. {@code gradeGrace} is each grade's grace days given, by grade
 *  (dated, from-date key grace-<grade>), blank meaning none. {@code gradeProofThreshold} is each grade's proof threshold
 *  given, by grade (dated, from-date key proof-threshold-<grade>), blank meaning none (the sheet's is then used).
 *  {@code pot} is the pot, blank meaning none (not dated). {@code parent} is the parent sheet's id, blank meaning none
 *  (not dated). {@code fiscalStartMonth} is the fiscal year start month, 1 to 12 (not dated). {@code alertThreshold} is the alert threshold, blank meaning off (not dated). */
public record SettingsRequest(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        java.util.Map<String, String> gradeTerms, String cap, java.util.Map<String, String> from,
        String proofThreshold, java.util.Map<String, String> permissions, String graceDays,
        String noteThreshold, String entryDate, java.util.Map<String, String> gradeGrace,
        java.util.Map<String, String> gradeProofThreshold, String pot, String parent,
        String fiscalStartMonth, String alertThreshold) {
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A validated settings form: which settings it saves, the clerk limit scaled to two decimals (null for
 *  no limit), the floor scaled to two decimals the terms in days and the late percent scaled to two decimals and the policy date (null when blank), and the period numbering from-date (null when blank: off), and the grade terms entered, by grade (in grade order; null
 *  when blank: the grade then uses the sheet's terms), and the cap scaled to two decimals (null for no cap), and the
 *  from-date given for each dated setting saved, by key (one not listed has none: it is saved from the sheet's today), and the proof threshold scaled to two decimals (null for none), and the
 *  permission matrix entries entered, by action (a comma separated list of roles; empty when blank: the standing rule), and the grace days (null when blank: off), and the note threshold
 *  scaled to two decimals (null for none), and the entry date (null when blank: off), and the grade grace days entered, by grade (in grade order; null when blank: none), and the grade proof thresholds entered, by
 *  grade, scaled to two decimals (in grade order; null when blank: none, the sheet's is then used), and the pot scaled to two decimals
 *  (null for none), and the parent sheet's id (null when blank: none), and the fiscal year start month (1 to 12), and the alert threshold scaled to two decimals (null for off). */
public record SettingsInput(boolean setsClerkLimit, BigDecimal clerkLimit, boolean setsFloor, BigDecimal floor, boolean setsTerms,
        Integer terms, boolean setsLatePct, BigDecimal latePct,
        boolean setsPolicyDate, LocalDate policyDate, boolean setsPeriodNumberingFrom, LocalDate periodNumberingFrom,
        java.util.Map<String, Integer> gradeTerms, boolean setsCap, BigDecimal cap, java.util.Map<String, LocalDate> from,
        boolean setsProofThreshold, BigDecimal proofThreshold, java.util.Map<String, String> permissions,
        boolean setsGraceDays, Integer graceDays, boolean setsNoteThreshold, BigDecimal noteThreshold,
        boolean setsEntryDate, LocalDate entryDate, java.util.Map<String, Integer> gradeGrace,
        java.util.Map<String, BigDecimal> gradeProofThreshold, boolean setsPot, BigDecimal pot,
        boolean setsParent, String parent, boolean setsFiscalStartMonth, Integer fiscalStartMonth,
        boolean setsAlertThreshold, BigDecimal alertThreshold) {
}
package net.officefloor.hq.app.settings;

import java.util.List;

/** A sheet's settings: its clerk limit (two decimals; null means no limit), its floor (two decimals:
 *  the least a live due can be), its terms (the business days after a claim's date that it is due by), its late percent (two decimals: what an
 *  overdue claim's due gains, of its figure, for every full 30 days it is overdue), the roles set on it, by user name. A name not listed is a clerk. And its policy date (yyyy-MM-dd; null when blank,
 *  meaning the sheet's today): a claim dated before it rounds half up, one on or after it half to even. And its period numbering from-date (yyyy-MM-dd; null when blank, meaning off):
 *  while set and the sheet's today is on or after it, a claim opened is numbered within its period. And each grade's own terms,
 *  by grade (a grade not listed uses the sheet's terms). And its cap (two decimals; null means none): a
 *  person's due-total is at most it. The clerk limit, floor, terms, late percent, grade terms and cap are those in
 *  force on the sheet's today; {@code dated} is every value recorded for each of them, by key (clerk-limit, floor,
 *  terms, terms-<grade>, late-pct, cap, proof-threshold, proof-threshold-<grade>), oldest from-date first. {@code permissions} is the permission
 *  matrix entries set, by action (open, settle, void, reassign, close, reopen), each a comma separated list of roles; an
 *  action not listed keeps the standing rule. {@code graceDays} is the days after a period's to-date it is left
 *  open (null when blank: off; not dated): changing the sheet's today closes each open period lapsed past them.
 *  {@code delegations} is each delegation of the steward role made on the sheet, oldest first.
 *  {@code entryDate} is the sheet's entry date (yyyy-MM-dd; null when blank: off; not dated): while set, it is the
 *  default date of a new claim instead of the sheet's today. {@code holidays} is the sheet's holidays (yyyy-MM-dd),
 *  earliest first: a claim's due-by, fixed when it is created, that falls on one is moved to the next day that is not one.
 *  {@code voidReasons} is the sheet's void reasons, in the order they were added: while there is one, voiding a claim
 *  needs one of them. {@code pot} is the sheet's pot (two decimals; null when blank: none; not dated): each member of
 *  a balanced pool gets a cut of it. {@code parent} is the sheet's parent sheet id (null when blank: none; not dated):
 *  a grade with no rate in force on a date takes the parent's, then its parent's, up to three levels up.
 *  {@code fiscalStartMonth} is the month (1 to 12; 1 unless set; not dated) the sheet's fiscal year starts in: a fiscal
 *  year is named FY<yyyy> by the calendar year its first day falls in.
 *  {@code alertThreshold} is the sheet's alert threshold (two decimals; null when blank: off; not dated): a person
 *  whose due-total goes from at or below it to above it is written an ALERT line. */
public record Settings(String clerkLimit, String floor, int terms, String latePct, List<Role> roles, String policyDate,
        String periodNumberingFrom, java.util.Map<String, Integer> gradeTerms, String cap,
        java.util.Map<String, List<DatedValue>> dated, java.util.Map<String, String> permissions, Integer graceDays,
        List<Delegation> delegations, String entryDate, List<String> holidays, List<String> voidReasons,
        String pot, String parent, int fiscalStartMonth, String alertThreshold) {
}
package net.officefloor.hq.app.settings;

/** A value a dated setting has from a date (yyyy-MM-dd); null when blank. */
public record DatedValue(String from, String value) {
}
package net.officefloor.hq.app.settings;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Save the settings given. A setting with a figure is recorded from its from-date (the sheet's today when
 *  none is given), replacing a value recorded from that date and keeping the others; its record ends with
 *  from=<date> when a from-date was given. */
public class SaveSettings {
    public void save(@PathVariable("sheetId") String sheetId, @Val SettingsInput input,
            ServerHttpConnection connection, SettingsRepository repository, SheetRepository sheets, Audit audit,
            Rollup rollup, Out<Settings> settings) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.sheetExists(id)) {
            throw new BadRequestException("no such sheet");
        }
        if (input.setsParent() && input.parent() != null) {
            if (input.parent().equals(id)) throw new BadRequestException("a sheet cannot be its own parent");
            if (!repository.sheetExists(input.parent())) throw new BadRequestException("no such parent sheet");
            if (repository.lineage(input.parent()).contains(id)) {
                throw new BadRequestException("the parent sheet has this sheet as an ancestor");
            }
        }
        LocalDate today = sheets.today(id);
        Rollup.Snapshot before = rollup.take(id);
        String prefix = "SETTING_CHANGED sheet=" + id + " by=" + by + " key=";
        if (input.setsClerkLimit()) {
            repository.setClerkLimit(id, from(input, "clerk-limit", today), input.clerkLimit());
            audit.record(prefix + "clerk-limit value="
                    + (input.clerkLimit() == null ? "" : SettingsRepository.money(input.clerkLimit())) + given(input, "clerk-limit"));
        }
        if (input.setsFloor()) {
            repository.setFloor(id, from(input, "floor", today), input.floor());
            audit.record(prefix + "floor value=" + SettingsRepository.money(input.floor()) + given(input, "floor"));
        }
        if (input.setsTerms()) {
            repository.setTerms(id, from(input, "terms", today), input.terms());
            audit.record(prefix + "terms value=" + input.terms() + given(input, "terms"));
        }
        input.gradeTerms().forEach((grade, terms) -> {
            repository.setGradeTerms(id, grade, from(input, "terms-" + grade, today), terms);
            audit.record(prefix + "terms-" + grade + " value=" + (terms == null ? "" : terms) + given(input, "terms-" + grade));
        });
        input.gradeGrace().forEach((grade, days) -> {
            repository.setGradeGrace(id, grade, from(input, "grace-" + grade, today), days);
            audit.record(prefix + "grace-" + grade + " value=" + (days == null ? "" : days) + given(input, "grace-" + grade));
        });
        if (input.setsLatePct()) {
            repository.setLatePct(id, from(input, "late-pct", today), input.latePct());
            audit.record(prefix + "late-pct value=" + SettingsRepository.money(input.latePct()) + given(input, "late-pct"));
        }
        if (input.setsPolicyDate()) {
            repository.setPolicyDate(id, input.policyDate());
            audit.record(prefix + "policy-date value="
                    + (input.policyDate() == null ? "" : input.policyDate().toString()));
        }
        if (input.setsPeriodNumberingFrom()) {
            repository.setPeriodNumberingFrom(id, input.periodNumberingFrom());
            audit.record(prefix + "period-numbering-from value="
                    + (input.periodNumberingFrom() == null ? "" : input.periodNumberingFrom().toString()));
        }
        if (input.setsCap()) {
            repository.setCap(id, from(input, "cap", today), input.cap());
            audit.record(prefix + "cap value="
                    + (input.cap() == null ? "" : SettingsRepository.money(input.cap())) + given(input, "cap"));
        }
        if (input.setsProofThreshold()) {
            repository.setProofThreshold(id, from(input, "proof-threshold", today), input.proofThreshold());
            audit.record(prefix + "proof-threshold value="
                    + (input.proofThreshold() == null ? "" : SettingsRepository.money(input.proofThreshold()))
                    + given(input, "proof-threshold"));
        }
        input.gradeProofThreshold().forEach((grade, threshold) -> {
            repository.setGradeProofThreshold(id, grade, from(input, "proof-threshold-" + grade, today), threshold);
            audit.record(prefix + "proof-threshold-" + grade + " value="
                    + (threshold == null ? "" : SettingsRepository.money(threshold)) + given(input, "proof-threshold-" + grade));
        });
        if (input.setsNoteThreshold()) {
            repository.setNoteThreshold(id, from(input, "note-threshold", today), input.noteThreshold());
            audit.record(prefix + "note-threshold value="
                    + (input.noteThreshold() == null ? "" : SettingsRepository.money(input.noteThreshold()))
                    + given(input, "note-threshold"));
        }
        if (input.setsGraceDays()) {
            repository.setGraceDays(id, input.graceDays());
            audit.record(prefix + "grace-days value=" + (input.graceDays() == null ? "" : input.graceDays()));
        }
        if (input.setsEntryDate()) {
            repository.setEntryDate(id, input.entryDate());
            audit.record(prefix + "entry-date value=" + (input.entryDate() == null ? "" : input.entryDate().toString()));
        }
        if (input.setsPot()) {
            repository.setPot(id, input.pot());
            audit.record(prefix + "pot value=" + (input.pot() == null ? "" : SettingsRepository.money(input.pot())));
        }
        if (input.setsParent()) {
            repository.setParent(id, input.parent());
            audit.record(prefix + "parent value=" + (input.parent() == null ? "" : input.parent()));
        }
        if (input.setsFiscalStartMonth()) {
            repository.setFiscalStartMonth(id, input.fiscalStartMonth());
            audit.record(prefix + "fiscal-start-month value=" + input.fiscalStartMonth());
        }
        if (input.setsAlertThreshold()) {
            repository.setAlertThreshold(id, input.alertThreshold());
            audit.record(prefix + "alert-threshold value="
                    + (input.alertThreshold() == null ? "" : SettingsRepository.money(input.alertThreshold())));
        }
        input.permissions().forEach((action, roles) -> {
            repository.setPermission(id, action, roles);
            audit.record(prefix + "perm-" + action + " value=" + roles);
        });
        rollup.record(id, by, before);
        settings.set(repository.load(id));
    }

    private static LocalDate from(SettingsInput input, String key, LocalDate today) {
        return input.from().getOrDefault(key, today);
    }

    private static String given(SettingsInput input, String key) {
        LocalDate from = input.from().get(key);
        return from == null ? "" : " from=" + from;
    }
}

