package net.officefloor.hq.app.settings;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Save the settings given. A setting with a figure is recorded from its from-date (the sheet's today when
 *  none is given), replacing a value recorded from that date and keeping the others; its record ends with
 *  from=<date> when a from-date was given. */
public class SaveSettings {
    public void save(@PathVariable("sheetId") String sheetId, @Val SettingsInput input,
            ServerHttpConnection connection, SettingsRepository repository, SheetRepository sheets, Audit audit,
            Rollup rollup, Out<Settings> settings) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.sheetExists(id)) {
            throw new BadRequestException("no such sheet");
        }
        if (input.setsParent() && input.parent() != null) {
            if (input.parent().equals(id)) throw new BadRequestException("a sheet cannot be its own parent");
            if (!repository.sheetExists(input.parent())) throw new BadRequestException("no such parent sheet");
            if (repository.lineage(input.parent()).contains(id)) {
                throw new BadRequestException("the parent sheet has this sheet as an ancestor");
            }
        }
        LocalDate today = sheets.today(id);
        Rollup.Snapshot before = rollup.take(id);
        String prefix = "SETTING_CHANGED sheet=" + id + " by=" + by + " key=";
        if (input.setsClerkLimit()) {
            repository.setClerkLimit(id, from(input, "clerk-limit", today), input.clerkLimit());
            audit.record(prefix + "clerk-limit value="
                    + (input.clerkLimit() == null ? "" : SettingsRepository.money(input.clerkLimit())) + given(input, "clerk-limit"));
        }
        if (input.setsFloor()) {
            repository.setFloor(id, from(input, "floor", today), input.floor());
            audit.record(prefix + "floor value=" + SettingsRepository.money(input.floor()) + given(input, "floor"));
        }
        if (input.setsTerms()) {
            repository.setTerms(id, from(input, "terms", today), input.terms());
            audit.record(prefix + "terms value=" + input.terms() + given(input, "terms"));
        }
        input.gradeTerms().forEach((grade, terms) -> {
            repository.setGradeTerms(id, grade, from(input, "terms-" + grade, today), terms);
            audit.record(prefix + "terms-" + grade + " value=" + (terms == null ? "" : terms) + given(input, "terms-" + grade));
        });
        input.gradeGrace().forEach((grade, days) -> {
            repository.setGradeGrace(id, grade, from(input, "grace-" + grade, today), days);
            audit.record(prefix + "grace-" + grade + " value=" + (days == null ? "" : days) + given(input, "grace-" + grade));
        });
        if (input.setsLatePct()) {
            repository.setLatePct(id, from(input, "late-pct", today), input.latePct());
            audit.record(prefix + "late-pct value=" + SettingsRepository.money(input.latePct()) + given(input, "late-pct"));
        }
        if (input.setsPolicyDate()) {
            repository.setPolicyDate(id, input.policyDate());
            audit.record(prefix + "policy-date value="
                    + (input.policyDate() == null ? "" : input.policyDate().toString()));
        }
        if (input.setsPeriodNumberingFrom()) {
            repository.setPeriodNumberingFrom(id, input.periodNumberingFrom());
            audit.record(prefix + "period-numbering-from value="
                    + (input.periodNumberingFrom() == null ? "" : input.periodNumberingFrom().toString()));
        }
        if (input.setsCap()) {
            repository.setCap(id, from(input, "cap", today), input.cap());
            audit.record(prefix + "cap value="
                    + (input.cap() == null ? "" : SettingsRepository.money(input.cap())) + given(input, "cap"));
        }
        if (input.setsProofThreshold()) {
            repository.setProofThreshold(id, from(input, "proof-threshold", today), input.proofThreshold());
            audit.record(prefix + "proof-threshold value="
                    + (input.proofThreshold() == null ? "" : SettingsRepository.money(input.proofThreshold()))
                    + given(input, "proof-threshold"));
        }
        input.gradeProofThreshold().forEach((grade, threshold) -> {
            repository.setGradeProofThreshold(id, grade, from(input, "proof-threshold-" + grade, today), threshold);
            audit.record(prefix + "proof-threshold-" + grade + " value="
                    + (threshold == null ? "" : SettingsRepository.money(threshold)) + given(input, "proof-threshold-" + grade));
        });
        if (input.setsNoteThreshold()) {
            repository.setNoteThreshold(id, from(input, "note-threshold", today), input.noteThreshold());
            audit.record(prefix + "note-threshold value="
                    + (input.noteThreshold() == null ? "" : SettingsRepository.money(input.noteThreshold()))
                    + given(input, "note-threshold"));
        }
        if (input.setsGraceDays()) {
            repository.setGraceDays(id, input.graceDays());
            audit.record(prefix + "grace-days value=" + (input.graceDays() == null ? "" : input.graceDays()));
        }
        if (input.setsEntryDate()) {
            repository.setEntryDate(id, input.entryDate());
            audit.record(prefix + "entry-date value=" + (input.entryDate() == null ? "" : input.entryDate().toString()));
        }
        if (input.setsPot()) {
            repository.setPot(id, input.pot());
            audit.record(prefix + "pot value=" + (input.pot() == null ? "" : SettingsRepository.money(input.pot())));
        }
        if (input.setsParent()) {
            repository.setParent(id, input.parent());
            audit.record(prefix + "parent value=" + (input.parent() == null ? "" : input.parent()));
        }
        if (input.setsFiscalStartMonth()) {
            repository.setFiscalStartMonth(id, input.fiscalStartMonth());
            audit.record(prefix + "fiscal-start-month value=" + input.fiscalStartMonth());
        }
        if (input.setsAlertThreshold()) {
            repository.setAlertThreshold(id, input.alertThreshold());
            audit.record(prefix + "alert-threshold value="
                    + (input.alertThreshold() == null ? "" : SettingsRepository.money(input.alertThreshold())));
        }
        input.permissions().forEach((action, roles) -> {
            repository.setPermission(id, action, roles);
            audit.record(prefix + "perm-" + action + " value=" + roles);
        });
        rollup.record(id, by, before);
        settings.set(repository.load(id));
    }

    private static LocalDate from(SettingsInput input, String key, LocalDate today) {
        return input.from().getOrDefault(key, today);
    }

    private static String given(SettingsInput input, String key) {
        LocalDate from = input.from().get(key);
        return from == null ? "" : " from=" + from;
    }
}

package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the settings form: the clerk limit is 0.00 or more with up to two decimals, blank meaning no
 *  limit; the floor is 0.00 or more with up to two decimals; the terms are a whole number of days, 0 to
 *  3650; the late percent is 0.00 or more with up to two decimals; the policy date is a date
 *  (yyyy-mm-dd), blank meaning the sheet's today; the period
 *  numbering from-date is a date, blank meaning off; a grade's (A, B or C) terms are like the sheet's, blank
 *  meaning the grade uses the sheet's terms; the cap is 0.00 or more with up to two decimals, blank meaning none; the proof threshold and the note threshold likewise. A from-date given for a
 *  setting with a figure is a date; blank is the sheet's today. A permission matrix entry (open, settle, void, reassign, close or reopen) is a comma separated
 *  list of roles (clerk, steward), blank keeping the standing rule. The grace days are a whole number of days, 0 to 3650, blank meaning off. The entry date is a date, blank meaning off. A grade's grace days are a whole number of days, 0 to 3650, blank meaning none. A grade's proof threshold is like the sheet's, blank meaning none. The pot is 0.00 or more with up to two decimals, blank meaning none. The parent is a sheet id, blank meaning none (checked when saved). The fiscal year start month is a month, 1 to 12. The alert threshold is 0.00 or more with up to two decimals, blank meaning off. A setting left out is not changed. */
public class ValidateSettings {
    private static final Pattern MONEY = Pattern.compile("\\d{1,9}(\\.\\d{1,2})?|\\.\\d{1,2}");
    private static final List<String> GRADES = List.of("A", "B", "C");
    private static final Pattern FISCAL_MONTH = Pattern.compile("\\d{1,2}");
    private static final Pattern TERMS = Pattern.compile("\\d{1,4}");

    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> settings)
            throws BadRequestException {
        String limit = request == null || request.clerkLimit() == null ? null : request.clerkLimit().trim();
        String floor = request == null || request.floor() == null ? null : request.floor().trim();
        String terms = request == null || request.terms() == null ? null : request.terms().trim();
        if (limit != null && !limit.isEmpty() && !MONEY.matcher(limit).matches()) {
            throw new BadRequestException("clerk limit must be 0.00 or more with up to two decimals");
        }
        if (floor != null && !MONEY.matcher(floor).matches()) {
            throw new BadRequestException("floor must be 0.00 or more with up to two decimals");
        }
        String latePct = request == null || request.latePct() == null ? null : request.latePct().trim();
        if (terms != null && (!TERMS.matcher(terms).matches() || Integer.parseInt(terms) > 3650)) {
            throw new BadRequestException("terms must be a whole number of days from 0 to 3650");
        }
        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
        Map<String, String> grades = request == null || request.gradeTerms() == null ? Map.of() : request.gradeTerms();
        for (String grade : GRADES) {
            String value = grades.get(grade) == null ? null : grades.get(grade).trim();
            if (value == null) continue;
            if (!value.isEmpty() && (!TERMS.matcher(value).matches() || Integer.parseInt(value) > 3650)) {
                throw new BadRequestException("terms for grade " + grade + " must be a whole number of days from 0 to 3650");
            }
            gradeTerms.put(grade, value.isEmpty() ? null : Integer.parseInt(value));
        }
        for (String grade : grades.keySet()) {
            if (!GRADES.contains(grade)) throw new BadRequestException("grade must be A, B or C");
        }
        Map<String, Integer> gradeGrace = new LinkedHashMap<>();
        Map<String, String> graces = request == null || request.gradeGrace() == null ? Map.of() : request.gradeGrace();
        for (String grade : GRADES) {
            String value = graces.get(grade) == null ? null : graces.get(grade).trim();
            if (value == null) continue;
            if (!value.isEmpty() && (!TERMS.matcher(value).matches() || Integer.parseInt(value) > 3650)) {
                throw new BadRequestException("grace days for grade " + grade + " must be a whole number of days from 0 to 3650");
            }
            gradeGrace.put(grade, value.isEmpty() ? null : Integer.parseInt(value));
        }
        for (String grade : graces.keySet()) {
            if (!GRADES.contains(grade)) throw new BadRequestException("grade must be A, B or C");
        }
        Map<String, BigDecimal> gradeProof = new LinkedHashMap<>();
        Map<String, String> proofs = request == null || request.gradeProofThreshold() == null ? Map.of()
                : request.gradeProofThreshold();
        for (String grade : GRADES) {
            String value = proofs.get(grade) == null ? null : proofs.get(grade).trim();
            if (value == null) continue;
            if (!value.isEmpty() && !MONEY.matcher(value).matches()) {
                throw new BadRequestException("proof threshold for grade " + grade + " must be 0.00 or more with up to two decimals");
            }
            gradeProof.put(grade, value.isEmpty() ? null : new BigDecimal(value).setScale(2));
        }
        for (String grade : proofs.keySet()) {
            if (!GRADES.contains(grade)) throw new BadRequestException("grade must be A, B or C");
        }
        if (latePct != null && !MONEY.matcher(latePct).matches()) {
            throw new BadRequestException("late percent must be 0.00 or more with up to two decimals");
        }
        String cap = request == null || request.cap() == null ? null : request.cap().trim();
        if (cap != null && !cap.isEmpty() && !MONEY.matcher(cap).matches()) {
            throw new BadRequestException("cap must be 0.00 or more with up to two decimals");
        }
        String proof = request == null || request.proofThreshold() == null ? null : request.proofThreshold().trim();
        if (proof != null && !proof.isEmpty() && !MONEY.matcher(proof).matches()) {
            throw new BadRequestException("proof threshold must be 0.00 or more with up to two decimals");
        }
        String note = request == null || request.noteThreshold() == null ? null : request.noteThreshold().trim();
        if (note != null && !note.isEmpty() && !MONEY.matcher(note).matches()) {
            throw new BadRequestException("note threshold must be 0.00 or more with up to two decimals");
        }
        String pot = request == null || request.pot() == null ? null : request.pot().trim();
        if (pot != null && !pot.isEmpty() && !MONEY.matcher(pot).matches()) {
            throw new BadRequestException("pot must be 0.00 or more with up to two decimals");
        }
        String alert = request == null || request.alertThreshold() == null ? null : request.alertThreshold().trim();
        if (alert != null && !alert.isEmpty() && !MONEY.matcher(alert).matches()) {
            throw new BadRequestException("alert threshold must be 0.00 or more with up to two decimals");
        }
        String parent = request == null || request.parent() == null ? null : request.parent().trim();
        String fiscal = request == null || request.fiscalStartMonth() == null ? null : request.fiscalStartMonth().trim();
        if (fiscal != null && (!FISCAL_MONTH.matcher(fiscal).matches() || Integer.parseInt(fiscal) < 1
                || Integer.parseInt(fiscal) > 12)) {
            throw new BadRequestException("fiscal year start month must be a month from 1 to 12");
        }
        String grace = request == null || request.graceDays() == null ? null : request.graceDays().trim();
        if (grace != null && !grace.isEmpty() && (!TERMS.matcher(grace).matches() || Integer.parseInt(grace) > 3650)) {
            throw new BadRequestException("grace days must be a whole number of days from 0 to 3650");
        }
        String policy = request == null || request.policyDate() == null ? null : request.policyDate().trim();
        LocalDate policyDate = null;
        if (policy != null && !policy.isEmpty()) {
            try {
                policyDate = LocalDate.parse(policy);
            } catch (DateTimeParseException e) {
                throw new BadRequestException("policy date must be a date (yyyy-mm-dd)");
            }
        }
        String numbering = request == null || request.periodNumberingFrom() == null ? null
                : request.periodNumberingFrom().trim();
        LocalDate numberingFrom = null;
        if (numbering != null && !numbering.isEmpty()) {
            try {
                numberingFrom = LocalDate.parse(numbering);
            } catch (DateTimeParseException e) {
                throw new BadRequestException("period numbering from must be a date (yyyy-mm-dd)");
            }
        }
        String entry = request == null || request.entryDate() == null ? null : request.entryDate().trim();
        LocalDate entryDate = null;
        if (entry != null && !entry.isEmpty()) {
            try {
                entryDate = LocalDate.parse(entry);
            } catch (DateTimeParseException e) {
                throw new BadRequestException("entry date must be a date (yyyy-mm-dd)");
            }
        }
        Map<String, String> permissions = new LinkedHashMap<>();
        Map<String, String> perms = request == null || request.permissions() == null ? Map.of() : request.permissions();
        for (String action : perms.keySet()) {
            if (!SettingsRepository.PERMISSION_ACTIONS.contains(action)) {
                throw new BadRequestException("permissions are for open, settle, void, reassign, close and reopen");
            }
        }
        for (String action : SettingsRepository.PERMISSION_ACTIONS) {
            String value = perms.get(action) == null ? null : perms.get(action).trim();
            if (value == null) continue;
            List<String> roles = new java.util.ArrayList<>();
            if (!value.isEmpty()) {
                for (String part : value.split(",", -1)) {
                    String r = part.trim();
                    if (!r.equals(SettingsRepository.CLERK) && !r.equals(SettingsRepository.STEWARD)) {
                        throw new BadRequestException("permission for " + action
                                + " must be a comma separated list of roles (clerk, steward)");
                    }
                    if (!roles.contains(r)) roles.add(r);
                }
            }
            permissions.put(action, String.join(",", roles));
        }
        Map<String, LocalDate> from = new LinkedHashMap<>();
        Map<String, String> froms = request == null || request.from() == null ? Map.of() : request.from();
        for (Map.Entry<String, String> given : froms.entrySet()) {
            String key = given.getKey();
            String date = given.getValue() == null ? "" : given.getValue().trim();
            if (date.isEmpty()) continue;
            boolean saved = switch (key) {
                case "clerk-limit" -> limit != null;
                case "floor" -> floor != null;
                case "terms" -> terms != null;
                case "late-pct" -> latePct != null;
                case "cap" -> cap != null;
                case "proof-threshold" -> proof != null;
                case "note-threshold" -> note != null;
                default -> (key.startsWith("terms-") && gradeTerms.containsKey(key.substring(6)))
                        || (key.startsWith("grace-") && gradeGrace.containsKey(key.substring(6)))
                        || (key.startsWith("proof-threshold-") && gradeProof.containsKey(key.substring(16)));
            };
            if (!saved) continue;
            try {
                from.put(key, LocalDate.parse(date));
            } catch (DateTimeParseException e) {
                throw new BadRequestException("from-date for " + key + " must be a date (yyyy-mm-dd)");
            }
        }
        settings.set(new SettingsInput(limit != null,
                limit == null || limit.isEmpty() ? null : new BigDecimal(limit).setScale(2),
                floor != null, floor == null ? null : new BigDecimal(floor).setScale(2),
                terms != null, terms == null ? null : Integer.parseInt(terms),
                latePct != null, latePct == null ? null : new BigDecimal(latePct).setScale(2),
                policy != null, policyDate, numbering != null, numberingFrom, gradeTerms,
                cap != null, cap == null || cap.isEmpty() ? null : new BigDecimal(cap).setScale(2), from,
                proof != null, proof == null || proof.isEmpty() ? null : new BigDecimal(proof).setScale(2), permissions,
                grace != null, grace == null || grace.isEmpty() ? null : Integer.parseInt(grace),
                note != null, note == null || note.isEmpty() ? null : new BigDecimal(note).setScale(2),
                entry != null, entryDate, gradeGrace, gradeProof,
                pot != null, pot == null || pot.isEmpty() ? null : new BigDecimal(pot).setScale(2),
                parent != null, parent == null || parent.isEmpty() ? null : parent,
                fiscal != null, fiscal == null ? null : Integer.parseInt(fiscal),
                alert != null, alert == null || alert.isEmpty() ? null : new BigDecimal(alert).setScale(2)));
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.history.HistoryRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SettingsRepository {
    public static final String CLERK = "clerk";
    public static final String STEWARD = "steward";
    /** A viewer sees everything and changes nothing. */
    public static final String VIEWER = "viewer";
    /** The actions the permission matrix covers, in the order shown. */
    public static final List<String> PERMISSION_ACTIONS = List.of("open", "settle", "void", "reassign", "close", "reopen");

    private final JdbcTemplate jdbc;
    private final HistoryRepository history;

    public SettingsRepository(JdbcTemplate jdbc, HistoryRepository history) {
        this.jdbc = jdbc;
        this.history = history;
    }

    public boolean sheetExists(String sheetId) {
        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, sheetId);
        return known != null && known > 0;
    }

    /** Whether a steward has archived the sheet: every change to it is then refused. */
    public boolean archived(String sheetId) {
        List<Boolean> found = jdbc.query("SELECT archived FROM sheet WHERE id = ?", (rs, i) -> rs.getBoolean("archived"), sheetId);
        return !found.isEmpty() && found.get(0);
    }

    /** The sheet's settings and roles, roles by user name: each dated setting as in force on the sheet's
     *  today, and every value recorded for each, by key. */
    public Settings load(String sheetId) {
        List<Role> roles = jdbc.query("SELECT user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
                (rs, i) -> new Role(rs.getString("user_name"), rs.getString("role")), sheetId);
        LocalDate today = today(sheetId);
        BigDecimal limit = clerkLimit(sheetId);
        BigDecimal cap = cap(sheetId);
        LocalDate policy = policyDate(sheetId);
        LocalDate numbering = periodNumberingFrom(sheetId);
        LocalDate entry = entryDate(sheetId);
        BigDecimal pot = pot(sheetId);
        BigDecimal alert = alertThreshold(sheetId);
        return new Settings(limit == null ? null : money(limit), money(floor(sheetId, today)), terms(sheetId, today),
                money(latePct(sheetId, today)), roles, policy == null ? null : policy.toString(),
                numbering == null ? null : numbering.toString(), gradeTerms(sheetId, today),
                cap == null ? null : money(cap), dated(sheetId), permissions(sheetId), graceDays(sheetId),
                delegations(sheetId), entry == null ? null : entry.toString(), holidays(sheetId),
                voidReasons(sheetId), pot == null ? null : money(pot), parent(sheetId), fiscalStartMonth(sheetId),
                alert == null ? null : money(alert));
    }

    /** The sheet's today; the real date when there is no such sheet. */
    public LocalDate today(String sheetId) {
        List<Date> found = jdbc.query("SELECT today FROM sheet WHERE id = ?", (rs, i) -> rs.getDate("today"), sheetId);
        return found.isEmpty() || found.get(0) == null ? LocalDate.now() : found.get(0).toLocalDate();
    }

    /** The value of a dated setting in force on a date: the one recorded with the latest from-date on or
     *  before it (a list holding null when that one is blank); an empty list when none is recorded then. */
    private List<String> on(String sheetId, String key, LocalDate date) {
        List<String> found = new java.util.ArrayList<>();
        jdbc.query("SELECT setting FROM setting_value WHERE sheet_id = ? AND setting_key = ? AND from_date <= ?"
                + " ORDER BY from_date DESC LIMIT 1",
                (org.springframework.jdbc.core.RowCallbackHandler) rs -> found.add(rs.getString("setting")),
                sheetId, key, Date.valueOf(date));
        return found;
    }

    /** Record a dated setting's value from a date (null for blank), replacing one recorded from that date. */
    public void record(String sheetId, String key, LocalDate from, String value) {
        jdbc.update("MERGE INTO setting_value (sheet_id, setting_key, from_date, setting) KEY (sheet_id, setting_key, from_date)"
                + " VALUES (?, ?, ?, ?)", sheetId, key, Date.valueOf(from), value);
        history.setting(sheetId, key, from, value);
    }

    /** Every value recorded for each dated setting, by key, each oldest from-date first. */
    public Map<String, List<DatedValue>> dated(String sheetId) {
        Map<String, List<DatedValue>> dated = new LinkedHashMap<>();
        jdbc.query("SELECT setting_key, from_date, setting FROM setting_value WHERE sheet_id = ? ORDER BY setting_key, from_date",
                (org.springframework.jdbc.core.RowCallbackHandler) rs -> dated
                        .computeIfAbsent(rs.getString("setting_key"), k -> new java.util.ArrayList<>())
                        .add(new DatedValue(rs.getDate("from_date").toLocalDate().toString(), rs.getString("setting"))),
                sheetId);
        return dated;
    }

    /** The sheet's clerk limit in force on its today; null when it has none. */
    public BigDecimal clerkLimit(String sheetId) {
        List<String> found = on(sheetId, "clerk-limit", today(sheetId));
        return found.isEmpty() || found.get(0) == null ? null : new BigDecimal(found.get(0));
    }

    public void setClerkLimit(String sheetId, LocalDate from, BigDecimal limit) {
        record(sheetId, "clerk-limit", from, limit == null ? null : money(limit));
    }

    /** The sheet's cap in force on its today: the most a person's due-total can be; null when it has none. */
    public BigDecimal cap(String sheetId) {
        List<String> found = on(sheetId, "cap", today(sheetId));
        return found.isEmpty() || found.get(0) == null ? null : new BigDecimal(found.get(0));
    }

    public void setCap(String sheetId, LocalDate from, BigDecimal cap) {
        record(sheetId, "cap", from, cap == null ? null : money(cap));
    }

    /** The sheet's proof threshold in force on a date: a claim of that date whose due is above it cannot be
     *  settled or approved without a proof; null when it has none. */
    public BigDecimal proofThreshold(String sheetId, LocalDate date) {
        List<String> found = on(sheetId, "proof-threshold", date);
        return found.isEmpty() || found.get(0) == null ? null : new BigDecimal(found.get(0));
    }

    public void setProofThreshold(String sheetId, LocalDate from, BigDecimal threshold) {
        record(sheetId, "proof-threshold", from, threshold == null ? null : money(threshold));
    }

    /** A grade's own proof threshold in force on a date; null when it has none then (the sheet's is used). */
    public BigDecimal gradeProofThreshold(String sheetId, String grade, LocalDate date) {
