              }}
            />{' '}
            <FromInput settingKey={`proof-threshold-${g}`} from={from} setFrom={setFrom} onChange={() => save.reset()} />{' '}
          </label>
        ))}
        <label>
          Note threshold{' '}
          <input
            data-testid="setting-note-threshold"
            inputMode="decimal"
